"""Scenario-specific employee decision semantics for FactoryBench-100.

The scenario catalog defines the Oracle operation.  This module defines the
business question behind that operation: what must be reconciled, what is
eligible, what is excluded, which independent constraint matters, and which
alternatives a real employee would compare.  Keeping all 100 entries explicit
prevents a superficially varied task set from collapsing onto one hidden
material-shortage template.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ScenarioDecisionSpec:
    mode: str
    subject: str
    scope_label: str
    eligible_label: str
    excluded_label: str
    constraint_label: str
    external_label: str
    capacity_label: str
    unit: str
    options: tuple[str, str, str]
    recommended_index: int
    source_document: str


def _s(
    mode: str,
    subject: str,
    scope_label: str,
    eligible_label: str,
    excluded_label: str,
    constraint_label: str,
    external_label: str,
    capacity_label: str,
    unit: str,
    options: tuple[str, str, str],
    recommended_index: int,
    source_document: str,
) -> ScenarioDecisionSpec:
    return ScenarioDecisionSpec(
        mode,
        subject,
        scope_label,
        eligible_label,
        excluded_label,
        constraint_label,
        external_label,
        capacity_label,
        unit,
        options,
        recommended_index,
        source_document,
    )


