VALID_MODES = {"plan", "quantity", "schedule", "financial", "identity", "forecast"}


def validate_decision_specs(titles: set[str]) -> None:
    missing = titles - set(SCENARIO_DECISION_SPECS)
    extra = set(SCENARIO_DECISION_SPECS) - titles
    invalid_modes = {
        title: spec.mode
        for title, spec in SCENARIO_DECISION_SPECS.items()
        if spec.mode not in VALID_MODES
    }
    invalid_options = {
        title: spec.options
        for title, spec in SCENARIO_DECISION_SPECS.items()
        if len(spec.options) != 3 or len(set(spec.options)) != 3
    }
    invalid_recommendations = {
        title: spec.recommended_index
        for title, spec in SCENARIO_DECISION_SPECS.items()
        if spec.recommended_index not in {0, 1, 2}
    }
    if missing or extra or invalid_modes or invalid_options or invalid_recommendations:
        raise ValueError(
            "invalid scenario decision specifications: "
            f"missing={sorted(missing)}, extra={sorted(extra)}, "
            f"modes={invalid_modes}, options={invalid_options}, "
            f"recommendations={invalid_recommendations}"
        )


__all__ = [
    "SCENARIO_DECISION_SPECS",
    "ScenarioDecisionSpec",
    "VALID_MODES",
    "validate_decision_specs",
]
